/**
 * src/services/user.service.js
 * Business logic for user accounts (admin): create, list, activate/deactivate
 * and reset password.
 *
 * PASSWORD POLICY
 *   - A temporary password is generated by the server, shown to the admin ONCE
 *     in the response, and only its hash is stored. It is never logged.
 *   - A login created without a password, and every admin reset, sets
 *     mustChangePassword: the user can do nothing but change the password
 *     until they have chosen their own.
 *   - A reset also invalidates every token issued before it.
 */

import User from "../models/User.js";
import Student from "../models/Student.js";
import { hashPassword } from "./auth.service.js";
import { generateTemporaryPassword } from "../utils/password.js";
import { ApiError } from "../utils/ApiError.js";
import { logger } from "../utils/logger.js";

const escapeRegex = (text) => text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function publicUser(user) {
  const student = user.student && typeof user.student === "object" && user.student.studentId
    ? { _id: user.student._id, studentId: user.student.studentId, name: user.student.name }
    : null;
  return {
    _id: user._id,
    email: user.email,
    role: user.role,
    student: student ?? user.student ?? null,
    isActive: user.isActive,
    mustChangePassword: Boolean(user.mustChangePassword),
    createdAt: user.createdAt,
  };
}

/**
 * Create a login. When `password` is omitted a temporary password is generated
 * and returned once; the account must change it at first login.
 */
export async function createUser({ email, password, role, studentId }) {
  let studentObjectId = null;

  if (role === "student") {
    const student = await Student.findOne({ studentId }).select("_id").lean();
    if (!student) {
      throw ApiError.badRequest(`No student record found with studentId "${studentId}".`);
    }
    const taken = await User.exists({ student: student._id });
    if (taken) {
      throw ApiError.conflict(`A login already exists for student "${studentId}".`);
    }
    studentObjectId = student._id;
  }

  const generated = password === undefined;
  const plain = generated ? generateTemporaryPassword() : password;
  const passwordHash = await hashPassword(plain);
  // Duplicate emails surface as a Mongo 11000 error -> 409 via the error middleware.
  const user = await User.create({
    email,
    passwordHash,
    role,
    student: studentObjectId,
    isActive: true,
    mustChangePassword: generated,
  });

  const result = { user: publicUser(user.toObject()) };
  if (generated) result.temporaryPassword = plain;
  return result;
}

export async function listUsers({ role, isActive, search, page = 1, limit = 50 }) {
  const filter = {};
  if (role) filter.role = role;
  if (isActive !== undefined) filter.isActive = isActive;
  if (search) filter.email = { $regex: escapeRegex(search), $options: "i" };

  const skip = (page - 1) * limit;
  const [users, total] = await Promise.all([
    User.find(filter)
      .populate("student", "studentId name")
      .sort({ createdAt: -1, _id: 1 })
      .skip(skip)
      .limit(limit)
      .lean(),
    User.countDocuments(filter),
  ]);

  return { users: users.map(publicUser), total, page, limit, totalPages: Math.ceil(total / limit) };
}

export async function getUserById(id) {
  const user = await User.findById(id).populate("student", "studentId name").lean();
  if (!user) throw ApiError.notFound("User");
  return publicUser(user);
}

/**
 * Activate or deactivate an account. A deactivated user is rejected on their
 * very next request (the token is checked against the database every time).
 * Guards: you cannot deactivate yourself, nor the last active admin.
 */
export async function setUserActive(id, isActive, actingUserId) {
  const target = await User.findById(id).select("role isActive").lean();
  if (!target) throw ApiError.notFound("User");

  if (!isActive) {
    if (String(id) === String(actingUserId)) {
      throw ApiError.conflict("You cannot deactivate your own account.");
    }
    if (target.role === "admin" && target.isActive) {
      const otherAdmins = await User.countDocuments({ role: "admin", isActive: true, _id: { $ne: id } });
      if (otherAdmins === 0) {
        throw ApiError.conflict("You cannot deactivate the last active admin.");
      }
    }
  }

  const user = await User.findByIdAndUpdate(id, { $set: { isActive } }, { new: true })
    .populate("student", "studentId name")
    .lean();
  logger.info({ userId: id, isActive, by: actingUserId }, "User active state changed");
  return publicUser(user);
}

/**
 * Admin reset: new temporary password (returned once), forced change at next
 * login, all existing tokens invalidated. Not allowed on your own account
 * (use change-password).
 */
export async function resetUserPassword(id, actingUserId) {
  if (String(id) === String(actingUserId)) {
    throw ApiError.badRequest("Use change-password to change your own password.");
  }
  const exists = await User.exists({ _id: id });
  if (!exists) throw ApiError.notFound("User");

  const temporaryPassword = generateTemporaryPassword();
  const passwordHash = await hashPassword(temporaryPassword);
  const user = await User.findByIdAndUpdate(
    id,
    { $set: { passwordHash, mustChangePassword: true, passwordChangedAt: new Date() } },
    { new: true }
  )
    .populate("student", "studentId name")
    .lean();

  logger.info({ userId: id, by: actingUserId }, "User password reset by admin");
  return { user: publicUser(user), temporaryPassword };
}
